import React, { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import './Sidebar.css';

const NAV = [
  { id: 'dashboard', icon: '◈', label: 'Dashboard' },
  { id: 'transactions', icon: '⇄', label: 'Transactions' },
  { id: 'analytics', icon: '◎', label: 'Analytics' },
  { id: 'budgets', icon: '◇', label: 'Budgets' },
];

export default function Sidebar({ active, onChange }) {
  const { user, signOut } = useAuth();
  const [mobileOpen, setMobileOpen] = useState(false);

  // Close mobile menu on route change
  useEffect(() => { setMobileOpen(false); }, [active]);
  // Close on resize to desktop
  useEffect(() => {
    const onResize = () => { if (window.innerWidth >= 768) setMobileOpen(false); };
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  const initials = user?.name ? user.name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase() : '??';

  return (
    <>
      {/* Mobile hamburger */}
      <button className="hamburger" onClick={() => setMobileOpen(v => !v)} aria-label="Toggle menu">
        <span className={`ham-line ${mobileOpen?'open':''}`} />
        <span className={`ham-line ${mobileOpen?'open':''}`} />
        <span className={`ham-line ${mobileOpen?'open':''}`} />
      </button>

      {/* Overlay */}
      {mobileOpen && <div className="sidebar-overlay" onClick={() => setMobileOpen(false)} />}

      <aside className={`sidebar ${mobileOpen ? 'mobile-open' : ''}`}>
        <div className="sidebar-logo">
          <span className="logo-icon">◈</span>
          <span className="logo-text">Finova</span>
        </div>

        <nav className="sidebar-nav">
          {NAV.map(item => (
            <button key={item.id}
              className={`nav-item ${active===item.id?'active':''}`}
              onClick={() => onChange(item.id)}
            >
              <span className="nav-icon">{item.icon}</span>
              <span className="nav-label">{item.label}</span>
              {active === item.id && <span className="nav-active-bar" />}
            </button>
          ))}
        </nav>

        <div className="sidebar-footer">
          <div className="user-row">
            <div className="user-avatar">{initials}</div>
            <div className="user-info">
              <span className="user-name">{user?.name || 'User'}</span>
              <span className="user-email">{user?.email || ''}</span>
            </div>
          </div>
          <button className="signout-btn" onClick={signOut} title="Sign out">
            ⎋ Sign Out
          </button>
        </div>
      </aside>
    </>
  );
}
